import { Router } from 'express';
import multer from 'multer';
import requireAuth from '../../middleware/requireAuth.js';
import { sendError } from '../../utils/respond.js';
import {
  getCountries,
  getCampusFeed,
  getCountryFeed,
  getGlobalFeed,
  getCampusNewCount,
  getPost,
  getPostReplies,
  getUserPosts,
  createPost,
  deletePost,
  setReaction,
  removeReaction,
} from './posts.controller.js';

const router = Router();

// Photos: field 'images', at most 3, 5 MB each, JPEG / PNG / WebP by declared
// type. Kept in memory: nothing is uploaded until moderation has run (runbook
// §1.10), and the controller still checks each one really is a readable photo.
const POST_MAX_PHOTOS = 3;
const PHOTO_MAX_BYTES = 5 * 1024 * 1024;
const PHOTO_TYPES = new Set(['image/jpeg', 'image/png', 'image/webp']);

const upload = multer({
  storage: multer.memoryStorage(),
  limits: { files: POST_MAX_PHOTOS, fileSize: PHOTO_MAX_BYTES },
  fileFilter: (req, file, cb) => {
    if (PHOTO_TYPES.has(file.mimetype)) return cb(null, true);
    return cb(Object.assign(new Error('INVALID_FILE_TYPE'), { code: 'INVALID_FILE_TYPE' }));
  },
});

/** Multer's errors, as the contract's codes. */
function uploadPhotos(req, res, next) {
  upload.array('images', POST_MAX_PHOTOS)(req, res, (err) => {
    if (!err) return next();
    if (err.code === 'INVALID_FILE_TYPE') return sendError(res, 400, 'INVALID_FILE_TYPE');
    if (err.code === 'LIMIT_FILE_SIZE') return sendError(res, 400, 'FILE_TOO_LARGE');
    if (err.code === 'LIMIT_FILE_COUNT' || (err.code === 'LIMIT_UNEXPECTED_FILE' && err.field === 'images')) {
      return sendError(res, 400, 'TOO_MANY_IMAGES', { max: POST_MAX_PHOTOS });
    }
    // A file under another field name, or a malformed form.
    if (err instanceof multer.MulterError) return sendError(res, 400, 'INVALID_FORMAT');
    return next(err);
  });
}

// The community: feeds, posts and replies. Mounted at /api/posts in app.js.
// Contract: backend/API.md, "posts module (Phase 7)". Every route requires the
// token.
//
// ⚠ ORDER MATTERS: the fixed paths come before '/:id', or Express would read
// "countries", "feed" or "by-user" as a post id.

// Block N-B part 1 — reading.
router.get('/countries', requireAuth, getCountries);
router.get('/feed/campus/new-count', requireAuth, getCampusNewCount);
router.get('/feed/campus', requireAuth, getCampusFeed);
router.get('/feed/country/:code', requireAuth, getCountryFeed);
router.get('/feed/global', requireAuth, getGlobalFeed);
router.get('/by-user/:userId', requireAuth, getUserPosts);
router.get('/:id/replies', requireAuth, getPostReplies);
router.get('/:id', requireAuth, getPost);

// Block N-B part 2 — posting, deleting and reacting. requireAuth runs before
// multer, so a caller without a token is turned away before any photo is
// buffered into memory.
router.post('/', requireAuth, uploadPhotos, createPost);
router.put('/:id/reaction', requireAuth, setReaction);
router.delete('/:id/reaction', requireAuth, removeReaction);
router.delete('/:id', requireAuth, deletePost);

export default router;
